-- L3 Staging rehearsal only; disposable provider fixtures never leave this transaction.
-- Apply after the automatic-reporting migration. No Meta requests or ad execution.
begin;
create temporary table ads_qa_checks(check_name text);
do $$
declare u uuid:=gen_random_uuid();actor uuid:=gen_random_uuid();role_id uuid:=gen_random_uuid();org uuid:=gen_random_uuid();brand uuid:=gen_random_uuid();other_brand uuid:=gen_random_uuid();
 reader_u uuid:=gen_random_uuid();reader_e uuid:=gen_random_uuid();reader_role uuid:=gen_random_uuid();s uuid;c jsonb;r jsonb;again jsonb;j uuid;l uuid;d date;denied boolean;account text:='99999999131001';report jsonb;before_social jsonb;
begin
 assert not has_function_privilege('authenticated','public.marketing_ads_schedule(uuid)','EXECUTE'),'Scheduler is server-only';
 assert not has_function_privilege('anon','public.marketing_ads_bind(uuid,uuid,text,uuid,jsonb,timestamptz,jsonb,integer)','EXECUTE'),'No public binding';
 assert not has_table_privilege('authenticated','marketing_private.ads_sync_jobs','SELECT'),'Private queue';
 insert into ads_qa_checks values('private authority grants');
 select jsonb_agg(to_jsonb(x) order by id) into before_social from marketing_connections x where channel in ('facebook','instagram');
 insert into auth.users(id,email,aud,role) values(u,'qa-ads-'||u||'@example.invalid','authenticated','authenticated'),(reader_u,'qa-ads-reader-'||reader_u||'@example.invalid','authenticated','authenticated');
 insert into roles(id,name,is_active,outlet_access_type) values(role_id,'qa_ads_'||role_id,true,'none'),(reader_role,'qa_ads_reader_'||reader_role,true,'none');
 insert into role_permissions(role_id,permission_id) select role_id,id from permissions where code in ('marketing_workspace.access','marketing_ads.connect','marketing_ads.view','marketing_ads.manage');
 insert into role_permissions(role_id,permission_id) select reader_role,id from permissions where code in ('marketing_workspace.access','marketing_ads.view');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 insert into employees(id,auth_user_id,full_name,email,role_id,enable_system_login,access_state,is_active,workplace)
 values(actor,u,'Ads QA rollback','qa-ads-'||u||'@example.invalid',role_id,true,'active',true,'Management'),(reader_e,reader_u,'Ads reader QA rollback','qa-ads-reader-'||reader_u||'@example.invalid',reader_role,true,'active',true,'Management');
 insert into organizations(id,name) values(org,'QA Ads rollback organization');
 insert into organization_memberships values(org,actor),(org,reader_e);
 insert into brands(id,organization_id,name) values(brand,org,'QA Ads permitted brand'),(other_brand,org,'QA Ads other brand');
 insert into marketing_role_scopes values(org,role_id,true),(org,reader_role,false);
 insert into marketing_role_brands values(org,reader_role,brand);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 r:=public.marketing_ads_begin(org,null,encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex'));s:=(r->>'id')::uuid;
 update marketing_private.oauth_sessions set consumed_at=now() where id=s;
 perform public.marketing_ads_stage(s,'99999999131002','{"ciphertext":"rollback-only"}',jsonb_build_array(jsonb_build_object('id',account,'name','QA rollback Ad Account')));
 c:=public.marketing_ads_bind(s,u,account,null,'{"ciphertext":"rollback-only"}',now()+interval '1 day',jsonb_build_object('id',account,'currency','MYR','timezone','America/New_York','read_verified',true,'manage_verified',false,'account_status',1,'tasks',jsonb_build_array('ANALYZE'),'granted_scopes',jsonb_build_array('ads_read')),null);
 assert c->'brand_id'='null'::jsonb and c#>>'{capabilities,execution_enabled}'='false','Organization-owned, no execution';
 d:=(now() at time zone 'America/New_York')::date;
 assert (select count(*)=2 from marketing_private.ads_sync_jobs where connection_id=(c->>'id')::uuid and source='initial'),'Automatic initial and comparison jobs';
 assert exists(select 1 from marketing_private.ads_sync_jobs where connection_id=(c->>'id')::uuid and date_from=d-29 and date_to=d),'Provider-local first 30 days';
 assert exists(select 1 from marketing_private.ads_sync_jobs where connection_id=(c->>'id')::uuid and date_from=d-59 and date_to=d-30),'Separate comparison period';
 again:=public.marketing_ads_bind(s,u,account,null,null,null,null,null);
 assert again=c,'Lost confirmation response is idempotent';
 assert (select granted_scopes='["ads_read"]'::jsonb from marketing_private.ads_accounts where connection_id=(c->>'id')::uuid),'Retry preserves granted scopes';
 assert (select count(*)=2 from marketing_private.ads_sync_jobs where connection_id=(c->>'id')::uuid),'No duplicate initial jobs';
 denied:=false;begin perform public.marketing_ads_bind(s,u,'99999999131099',null,null,null,null,null);exception when others then denied:=true;end;assert denied,'Changed confirmation rejected';
 insert into ads_qa_checks values('automatic initial reporting, provider timezone, retry identity and no execution');
 j:=public.marketing_ads_request_sync((c->>'id')::uuid,d-29,d);
 assert j=public.marketing_ads_request_sync((c->>'id')::uuid,d-29,d),'Manual recovery coalesces';
 assert public.marketing_ads_schedule((c->>'id')::uuid)=0,'Scheduler coalesces';
 -- Give this disposable queue precedence without changing another account's work.
 update marketing_private.ads_sync_jobs set created_at=now()-interval '1 day' where connection_id=(c->>'id')::uuid;
 r:=public.marketing_ads_claim();assert r->>'connection_id'=c->>'id','Fixture claim';j:=(r->>'id')::uuid;l:=(r->>'lease')::uuid;
 report:=jsonb_build_object('account',jsonb_build_object('id',account,'currency','MYR','timezone','America/New_York','account_status',1,'tasks',jsonb_build_array('ANALYZE'),'manage_verified',false,'granted_scopes',jsonb_build_array('ads_read')),'date_from',r->>'date_from','date_to',r->>'date_to','configs',jsonb_build_object('campaigns','[]'::jsonb,'adsets','[]'::jsonb,'ads','[]'::jsonb),'insights',jsonb_build_object('account','[]'::jsonb,'campaign','[]'::jsonb,'adset','[]'::jsonb,'ad','[]'::jsonb,'daily','[]'::jsonb),'warnings','{}'::jsonb);
 perform public.marketing_ads_finish(j,l,report);
 assert exists(select 1 from marketing_private.ads_snapshots where connection_id=(c->>'id')::uuid and payload#>'{insights,account}'='[]'::jsonb),'Empty evidence retained without zeros';
 r:=public.marketing_ads_claim();assert r->>'connection_id'=c->>'id','Comparison claim';j:=(r->>'id')::uuid;l:=(r->>'lease')::uuid;
 perform public.marketing_ads_finish(j,l,null,'meta_error_429');
 assert (select state='retry' and attempts=1 and retry_at between now()+interval '50 seconds' and now()+interval '70 seconds' from marketing_private.ads_sync_jobs where id=j),'One-minute retry';
 assert (select read_verified from marketing_private.ads_accounts where connection_id=(c->>'id')::uuid),'Transient report error does not revoke verified permission';
 update marketing_private.ads_sync_jobs set retry_at=now()-interval '1 second',attempts=3 where id=j;
 r:=public.marketing_ads_claim();assert (r->>'id')::uuid=j,'Bounded retry claim';perform public.marketing_ads_finish(j,(r->>'lease')::uuid,null,'meta_error_429');
 assert (select state='failed' and attempts=4 from marketing_private.ads_sync_jobs where id=j),'Four-attempt terminal limit';
 assert (select next_sync_at>=now()+interval '6 hours' from marketing_private.ads_accounts where connection_id=(c->>'id')::uuid),'Six-hour failure cooldown';
 update marketing_private.ads_sync_jobs set state='leased',lease=gen_random_uuid(),lease_until=now()-interval '1 second',attempts=4 where id=j;
 update marketing_private.ads_accounts set next_sync_at=now()+interval '5 minutes' where connection_id=(c->>'id')::uuid;
 perform public.marketing_ads_claim();
 assert (select state='failed' from marketing_private.ads_sync_jobs where id=j),'Expired final lease terminalized';
 assert (select next_sync_at>=now()+interval '6 hours' and automatic_error='sync_retry_limit' from marketing_private.ads_accounts where connection_id=(c->>'id')::uuid),'Lost-worker failure also cools down';
 insert into ads_qa_checks values('coalescing, empty evidence, transient retry, permission retention and terminal cooldown');
 update marketing_private.ads_accounts set next_sync_at=now()-interval '1 second' where connection_id=(c->>'id')::uuid;
 assert public.marketing_ads_schedule((c->>'id')::uuid)=2,'Background refresh resumes after cooldown';
 update marketing_private.ads_sync_jobs set created_at=now()-interval '1 day' where connection_id=(c->>'id')::uuid and source='refresh';
 r:=public.marketing_ads_claim();assert r->>'connection_id'=c->>'id','Refresh fixture claim';
 perform public.marketing_ads_finish((r->>'id')::uuid,(r->>'lease')::uuid,null,'ads_read_not_granted');
 assert (select next_sync_at is null and not read_verified from marketing_private.ads_accounts where connection_id=(c->>'id')::uuid),'Revoked scope stops automatic provider reads';
 assert not exists(select 1 from marketing_private.ads_sync_jobs where connection_id=(c->>'id')::uuid and state in ('queued','retry','leased')),'Sibling unauthorized work cancelled';
 insert into ads_qa_checks values('automatic recovery and permission-blocked stop');
 -- Reconnect the same slot; no brand, campaign attribution or execution reassignment.
 r:=public.marketing_ads_begin(org,null,encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex'));s:=(r->>'id')::uuid;
 update marketing_private.oauth_sessions set consumed_at=now() where id=s;
 perform public.marketing_ads_stage(s,'99999999131002','{"ciphertext":"rollback-only"}',jsonb_build_array(jsonb_build_object('id',account,'name','QA rollback Ad Account')));
 again:=public.marketing_ads_bind(s,u,account,null,'{"ciphertext":"rollback-only"}',now()+interval '1 day',report->'account'||'{"read_verified":true}',1);
 assert again->>'id'=c->>'id' and again->>'credential_generation'='2','Reconnect preserves slot and advances generation';
 assert (select count(*)=2 from marketing_private.ads_sync_jobs where connection_id=(c->>'id')::uuid and generation=2 and source='initial'),'Reconnect reschedules initial verification';
 assert (select automatic_error is null and next_sync_at is not null from marketing_private.ads_accounts where connection_id=(c->>'id')::uuid),'Reconnect clears blocked schedule';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',reader_u,'role','authenticated')::text,true);
 denied:=false;begin perform public.marketing_ads_request_sync((c->>'id')::uuid,d-29,d);exception when insufficient_privilege then denied:=true;end;assert denied,'Brand-only reader cannot queue shared reporting';
 denied:=false;begin perform public.marketing_ads_begin(org,null,repeat('d',64));exception when insufficient_privilege then denied:=true;end;assert denied,'Brand-only reader cannot bind account';
 r:=public.marketing_ads_read(org,brand,d-29,d);assert r->'accounts'='[]'::jsonb and r->'reports'='[]'::jsonb,'Unassigned shared data hidden';
 denied:=false;begin perform public.marketing_ads_read(org,other_brand,d-29,d);exception when insufficient_privilege then denied:=true;end;assert denied,'Cross-brand read denied';
 insert into ads_qa_checks values('same-account reconnect, generation pinning and brand-only isolation');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 perform public.marketing_meta_disconnect((c->>'id')::uuid);
 assert not exists(select 1 from marketing_private.ads_accounts where connection_id=(c->>'id')::uuid),'Disconnect erases scheduling projection';
 assert not exists(select 1 from marketing_private.ads_snapshots where connection_id=(c->>'id')::uuid),'Disconnect erases reporting';
 r:=public.marketing_ads_read(org,null,d-29,d);
 select value into again from jsonb_array_elements(r->'accounts') where value->>'id'=c->>'id';
 assert again->>'account_slot'=account and again->'account_id'='null'::jsonb,'Disconnected slot exposed only in scoped account projection';
 r:=public.marketing_ads_begin(org,null,encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex'));s:=(r->>'id')::uuid;
 update marketing_private.oauth_sessions set consumed_at=now() where id=s;
 perform public.marketing_ads_stage(s,'99999999131002','{"ciphertext":"rollback-only"}',jsonb_build_array(jsonb_build_object('id',account,'name','QA rollback Ad Account')));
 r:=public.marketing_ads_bind(s,u,account,null,'{"ciphertext":"rollback-only"}',now()+interval '1 day',report->'account'||'{"read_verified":true}',(again->>'generation')::integer);
 assert r->>'id'=c->>'id' and (r->>'credential_generation')::integer=(again->>'generation')::integer+1,'Client-projected generation reconnects the disconnected slot';
 assert r#>>'{capabilities,execution_enabled}'='false','Reconnect never enables execution';
 insert into ads_qa_checks values('disconnect/read/reconnect preserves slot and client generation');
 assert before_social is not distinct from (select jsonb_agg(to_jsonb(x) order by id) from marketing_connections x where channel in ('facebook','instagram')),'Social connections preserved';
 insert into ads_qa_checks values('credential erasure, social isolation and unchanged execution controls');
end;$$;
select jsonb_agg(check_name) passed_checks from ads_qa_checks;
rollback;
